 */
function buildRouteMinFilter(
  range: FilterConfig['range'],
  minFlightsPerRoute: number,
): ReturnType<typeof sql> {
  let routeMinDateFilter: ReturnType<typeof sql>;

  if (range.type === 'custom' && range.dateFrom && range.dateTo) {
